package com.warehouse.twin.service;
import com.warehouse.twin.dto.EventReviewRequest;import com.warehouse.twin.entity.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.Set;
@Service public class EventReviewService {private final WarehouseEventService events;private final DisciplineRecordService records;public EventReviewService(WarehouseEventService e,DisciplineRecordService r){events=e;records=r;}
    @Transactional public synchronized WarehouseEvent review(Long id,EventReviewRequest r){if(!Set.of("CONFIRMED","DISMISSED").contains(r.decision()))throw new IllegalArgumentException("decision 必须是 CONFIRMED 或 DISMISSED");WarehouseEvent e=events.getById(id);if(e==null)throw new IllegalArgumentException("事件不存在");if(!"PENDING".equals(e.getStatus()))throw new IllegalArgumentException("事件已经复核");e.setStatus(r.decision());e.setRemark(r.reviewer()+": "+(r.remark()==null?"":r.remark()));events.updateById(e);if("CONFIRMED".equals(r.decision())&&r.points()!=null&&r.points()!=0){if(r.personId()==null||r.personId().isBlank())throw new IllegalArgumentException("执行奖惩时 personId 不能为空");DisciplineRecord d=new DisciplineRecord();d.setEventId(id);d.setPersonId(r.personId());d.setActionType(r.points()>0?"REWARD":"PENALTY");d.setPoints(r.points());d.setWarningLevel(r.warningLevel());d.setReason(r.remark());d.setReviewer(r.reviewer());d.setReviewedAt(LocalDateTime.now());records.save(d);}return e;}}
